cypress_script:
describe('Multi-level Navigation Menu', () => {
  it('should navigate to sub items upon clicking Main Item 1', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').click();
    cy.get('a').contains('Sub Item').should('be.visible');
    cy.get('a').contains('SUB SUB LIST »').should('be.visible').click();
    cy.get('a').contains('Sub Sub Item 1').should('be.visible');
    cy.get('a').contains('Sub Sub Item 2').should('be.visible');
  });

  it('should not navigate on clicking Sub Item without action', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').click();
    cy.get('a').contains('Sub Item').click();
    cy.url().should('eq', 'https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level Navigation Menu', () => {
  test('should navigate to sub items upon clicking Main Item 1', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('a:text("Main Item 1")');
    await expect(page.locator('a:text("Sub Item")')).toBeVisible();
    await expect(page.locator('a:text("SUB SUB LIST »")')).toBeVisible();
    await page.click('a:text("SUB SUB LIST »")');
    await expect(page.locator('a:text("Sub Sub Item 1")')).toBeVisible();
    await expect(page.locator('a:text("Sub Sub Item 2")')).toBeVisible();
  });

  test('should not navigate on clicking Sub Item without action', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('a:text("Main Item 1")');
    await page.click('a:text("Sub Item")');
    await expect(page).toHaveURL('https://demoqa.com/menu');
    await expect(page.locator('a:text("Main Item 1")')).toBeVisible();
  });
});
